 public function __construct(Orion_Conversation_Service $c,Orion_Rate_Limiter $r,Orion_Knowledge_Base $k,Orion_Semantic_Product_Planner $p,Orion_Intent_Classifier $i,Orion_Context_Manager $x,Orion_Manager_Handoff $h,Orion_AI_Trace_Service $t){$this->conversations=$c;$this->rate_limiter=$r;$this->knowledge=$k;$this->planner=$p;$this->classifier=$i;$this->context=$x;$this->handoff=$h;$this->traces=$t;}
 public function respond(string $message,string $session_key=''):array|WP_Error{$this->started=microtime(true);$this->pending_manager_response=null;$message=trim(sanitize_textarea_field($message));if($message===''||mb_strlen($message)>1200)return new WP_Error('invalid_message','Please enter a message of up to 1,200 characters.',array('status'=>400));$settings=Orion_AI_Settings::get();if($settings['enabled']!=='1')return new WP_Error('disabled','The assistant is currently unavailable.',array('status'=>503));$rate=$this->rate_limiter->check($settings);if(is_wp_error($rate))return$rate;$conversation=$this->conversations->resolve($session_key,$settings);if(is_wp_error($conversation))return$conversation;$id=(int)$conversation['id'];$this->pending_manager_response=$this->handoff->pending_response($id);$this->trace_id=$this->traces->begin($id,$message,$settings);$history=$this->conversations->history($id);$state=$this->conversations->state($id);$classification=$this->classifier->classify($message,$history,$state,$settings);$this->traces->update($this->trace_id,array('intent'=>$classification['intent'],'topic'=>$classification['topic'],'stages'=>array('classification'=>$classification)));$diagnostic_status=(string)($classification['_diagnostic']['status']??'');if(in_array($diagnostic_status,array('provider_error','invalid_output'),true)){$stage='provider_error'===$diagnostic_status?'classification_provider_error':'classification_invalid_output';$reason=(string)($classification['_diagnostic']['error']??'The AI provider returned no valid routing response.');$this->traces->complete($this->trace_id,'failed',$stage,$reason,$this->elapsed());return new WP_Error('ai_temporarily_unavailable','The AI service is temporarily unavailable. Please try again.',array('status'=>503,'trace_id'=>$this->trace_id));}$state=$this->context->apply($state,$classification);$this->conversations->save_state($id,$state);$this->traces->update($this->trace_id,array('stages'=>array('context'=>array('saved