  if(!empty($classification['needs_clarification'])&&!empty($classification['clarifying_questions']))return$this->finish($conversation,$settings,$message,'I need a little more information before I can give you a reliable answer.',array(),array(),array(),'clarification_requested',$classification['clarifying_questions'],'clarification');
  return match($classification['intent']){'store_policy'=>$this->policy($conversation,$settings,$message,$classification,$state),'project_recommendation','product_search'=>$this->products($conversation,$settings,$message,$classification,$state),'manager_follow_up'=>$this->refer($conversation,$settings,$message,$classification,$state,'This question needs confirmation from our team.','classifier_requested_handoff'),default=>$this->general($conversation,$settings,$message,$history,$state)};
