 private function policy(array $conversation,array $settings,string $message,array $classification,array $state):array|WP_Error{$query=$classification['policy_query']?:$message;$docs=$this->knowledge->relevant($query,5);$this->traces->update($this->trace_id,array('stages'=>array('knowledge'=>array('query'=>$query,'result_count'=>count($docs),'sources'=>array_values(array_unique(array_filter(array_column($docs,'source_url'))))))));if(!$docs)return$this->refer($conversation,$settings,$message,$classification,$state,'I do not have confirmed information about that in the store knowledge base.','knowledge_no_results');$provider=Orion_AI_Provider_Factory::create($settings);$prompt='Answer only from supplied store knowledge. Return JSON only: {"supported":true,"answer":"..."}. Set supported false if documents do not explicitly answer. Never infer delivery areas, prices, dates, policies or guarantees.';$result=$provider->chat(array(array('role'=>'system','content'=>$prompt),array('role'=>'user','content'=>wp_json_encode(array('question'=>$message,'documents'=>$docs)))));$data=!empty($result['ok'])?$this->decode((string)($result['message']['content']??'')):null;$this->traces->update($this->trace_id,array('stages'=>array('policy_validation'=>array('provider_ok'=>!empty($result['ok']),'supported'=>!empty($data['supported']),'usage'=>$result['usage']??array(),'attempts'=>$result['attempts']??array(),'fallback_used'=>!empty($result['fallback_used'])))));if(!is_array($data)||empty($data['supported'])||empty($data['answer']))return$this->refer($conversation,$settings,$message,$classification,$state,'The available store information does not explicitly answer that question.','knowledge_not_supported');return$this->finish($conversation,$settings,$message,sanitize_textarea_field((string)$data['answer']),array(),$this->sources($docs),$result['usage']??array(),'policy_answered');}
 private function products(array $conversation,array $settings,string $message,array $classification,array $state):array|WP_Error{$kit=$this->planner->recommend($classification,$state,$settings);$required_missing=array();foreach($kit['plan']as$group)if(!empty($group['required'])&&in_array($group['role'],$kit['missing_roles'],true))$required_missing[]=$group['role'];$this->traces->update($this->trace_id,array('stages'=>array('catalogue'=>array('roles'=>array_column($kit['plan'],'role'),'candidate_counts'=>array_map(static fn($g)=>count($g['candidates']??array()),$kit['plan']),'candidate_summaries'=>array_map(static fn($g)=>array('role'=>$g['role']??'','items'=>array_map(static fn($c)=>array('id'=>$c['id']??0,'name'=>$c['name']??'','retrieval'=>$c['retrieval']??array()),$g['candidates']??array())),$kit['plan']),'selected'=>array_map(static fn($p)=>array('id'=>$p['id'],'role'=>$p['kit_role']??'','need_key'=>$p['need_key']??'','recommendation_reason'=>$p['recommendation_reason']??'','selection_evidence'=>$p['selection_evidence']??array()),$kit['products']),'missing_roles'=>$kit['missing_roles'],'conditional_roles'=>$kit['conditional_roles']??array(),'selection_diagnostic'=>$kit['diagnostic']??array(),'required_missing'=>$required_missing))));if(!$kit['products']||$required_missing)return$this->refer($conversation,$settings,$message,$classification,array_merge($state,array('missing_roles'=>$required_missing?:$kit['missing_roles'])),'I could not find enough confirmed suitable products in the live catalogue.',$kit['products']?'required_product_missing':'catalogue_no_candidates',$kit['products']);$provider=Orion_AI_Provider_Factory::create($settings);$prompt='Write a concise shopping answer using only verified live products. Explain each selected product role. State every non-empty selection_evidence uncertainty clearly and never turn it into a positive compatibility claim. Never invent suitability, compatibility, quantity, coverage, price, stock or links. A product volume or pack size alone does not prove that it is the right quantity for the project area. State quantity or coverage only when explicit numeric manufacturer coverage is present in verified_products; otherwise tell the customer to check the product instructions and do not call the pack size appropriate for the area. Never cite the recommendation itself as evidence. Present missing application tools briefly. conditional_roles are deferred preparation items, not missing products: explain briefly that they may be needed only when surface condition requires them. Never imply that every optional role is required. Follow the supplied product order, which is already prioritised for visible cards.';$result=$provider->chat(array(array('role'=>'system','content'=>$prompt),array('role'=>'user','content'=>wp_json_encode(array('request'=>$message,'state'=>$state,'verified_products'=>$kit['products'],'missing_roles'=>$kit['missing_roles'],'conditional_roles'=>$kit['conditional_roles']??array())))));$this->traces->update($this->trace_id,array('stages'=>array('answer_generation'=>array('attempts'=>$result['attempts']??array(),'fallback_used'=>!empty($result['fallback_used'])))));$answer=!empty($result['ok'])?trim((string)($result['message']['content']??'')):'';if($answer==='')$answer='I found verified products for this request. Please review the product cards and manufacturer instructions.';return$this->finish($conversation,$settings,$message,$answer,$kit['products'],array(),$result['usage']??array(),'project_recommendation_completed');}
 private function general(array $conversation,array $settings,string $message,array $history,array $state):array|WP_Error{$provider=Orion_AI_Provider_Factory::create($settings);$system=$settings['system_prompt'].' Do not invent store-specific facts, product availability, policies or prices.';$messages=array(array('role'=>'system','content'=>$system));foreach(array_slice($history,-8)as$item)$messages[]=array('role'=>$item['role'],'content'=>$item['content']);$messages[]=array('role'=>'user','content'=>$message);$result=$provider->chat($messages);$this->traces->update($this->trace_id,array('stages'=>array('answer_generation'=>array('attempts'=>$result['attempts']??array(),'fallback_used'=>!empty($result['fallback_used'])))));if(empty($result['ok'])){$this->traces->complete($this->trace_id,'failed','answer_provider_error',(string)($result['error']??'Provider error'),$this->elapsed());return new WP_Error('ai_error',$result['error'],array('status'=>502));}$answer=trim((string)($result['message']['content']??''))?:'I could not prepare a reliable answer.';return$this->finish($conversation,$settings,$message,$answer,array(),array(),$result['usage']??array(),'general_answered');}
 private function refer(array $conversation,array $settings,string $message,array $classification,array $state,string $reason,string $stage,array $products=array()):array|WP_Error{$id=$this->handoff->create((int)$conversation['id'],$message,array('trace_id'=>$this->trace_id,'reason'=>$reason,'failure_stage'=>$stage,'classification'=>$classification,'state'=>$state));$this->traces->update($this->trace_id,array('stages'=>array('handoff'=>array('handoff_id'=>$id,'reason'=>$reason))));$this->conversations->record_event('manager_follow_up_needed',array('handoff_id'=>$id,'trace_id'=>$this->trace_id,'topic'=>$classification['topic']??''),(int)$conversation['id']);$answer=$reason.' I have added this question to the manager follow-up queue'.($id?' as reference #'.$id:'').'.';return$this->finish($conversation,$settings,$message,$answer,$products,array(),array(),'manager_follow_up_created',array(),'manager_follow_up',$stage,$reason);}
 private function finish(array $conversation,array $settings,string $question,string $answer,array $products,array $sources,array $usage,string $event,array $questions=array(),string $trace_status='completed',string $failure_stage='',string $failure_reason=''):array|WP_Error{$id=(int)$conversation['id'];$limit=(int)$settings['questions_per_session'];if(!$this->conversations->increment($id,$limit)){$this->traces->complete($this->trace_id,'failed','session_limit','Question limit reached',$this->elapsed());return new WP_Error('session_limit','This chat session has ended.',array('status'=>429));}$manager_response_id=0;if($this->pending_manager_response){$pending_id=(int)($this->pending_manager_response['id']??0);$pending_text=trim((string)($this->pending_manager_response['manager_response']??''));if($pending_id>0&&$pending_text!==''&&$this->handoff->mark_response_delivered($pending_id)){$manager_response_id=$pending_id;$answer='Update from our team for request #'.$pending_id.":\n".$pending_text."\n\n".$answer;$this->conversations->record_event('manager_response_delivered',array('handoff_id'=>$pending_id,'trace_id'=>$this->trace_id),$id);}$this->pending_manager_response=null;}$saved_answer=$answer;if($questions)$saved_answer.="\n".implode("\n",array_map(static fn($q)=>'- '.$q,$questions));$this->conversations->save_exchange($id,$question,$saved_answer,$usage);$this->conversations->record_event($event,array('products'=>count($products),'trace_id'=>$this->trace_id),$id);$this->traces->complete($this->trace_id,$trace_status,$failure_stage,$failure_reason,$this->elapsed(),array('stages'=>array('response'=>array('event'=>$event,'product_count'=>count($products),'usage'=>$usage,'clarifying_questions'=>$questions,'manager_response_id'=>$manager_response_id))));return array('answer'=>$answer,'message'=>$answer,'questions'=>$questions,'products'=>$this->unique_products($products),'estimate'=>null,'sources'=>$sources,'actions'=>$products?array(array('type'=>'add_to_cart','label'=>