 private function elapsed():int{return(int)round((microtime(true)-$this->started)*1000);}private function decode(string $text):?array{$text=trim(preg_replace('/^```(?:json)?\s*|\s*```$/i','',trim($text)));$data=json_decode($text,true);if(is_array($data))return$data;if(preg_match('/\{[\s\S]*\}/',$text,$m)){$data=json_decode($m[0],true);return is_array($data)?$data:null;}return null;}private function sources(array $docs):array{$out=array();foreach($docs as$d)if(!empty($d['source_url']))$out[$d['source_url']]=array('title'=>$d['title'],'url'=>$d['source_url']);return array_values($out);}private function unique_products(array $products):array{$out=array();foreach($products as$p)if(!empty($p['id']))$out[(int)$p['id']]=$p;return array_values($out);}
